using System;
using System.Collections.Generic;
using UnityEngine;

namespace OwnSpace.Content
{
    /// <summary>Looks up the prefab that shows one catalog item. Implemented by <see cref="CatalogPrefabs"/>; fake it in tests.</summary>
    public interface ICatalogPrefabs
    {
        /// <summary>True and the prefab when the catalog id has one; false (and null) otherwise. No allocation after the first call.</summary>
        bool TryGetPrefab(string catalogId, out GameObject prefab);
    }

    /// <summary>
    /// Maps catalog id to prefab. Generated by the <c>content</c> editor script
    /// (menu: OwnSpace/Content/Build Placeholder Prefabs); do not edit by hand.
    /// Every prefab has its pivot at the bottom center of the item's catalog size and +Z as its front.
    /// </summary>
    [CreateAssetMenu(menuName = "OwnSpace/Catalog Prefabs", fileName = "CatalogPrefabs")]
    public sealed class CatalogPrefabs : ScriptableObject, ICatalogPrefabs
    {
        [Serializable]
        public struct Entry
        {
            [Tooltip("Catalog item id from catalog.json.")] public string id;
            [Tooltip("Prefab that shows the item.")] public GameObject prefab;
        }

        [SerializeField, Tooltip("Generated list; one entry per catalog item.")]
        Entry[] _entries = Array.Empty<Entry>();

        Dictionary<string, GameObject> _byId;

        public int Count => _entries.Length;

        public bool TryGetPrefab(string catalogId, out GameObject prefab)
        {
            prefab = null;
            if (string.IsNullOrEmpty(catalogId)) return false;
            if (_byId == null) Rebuild();
            return _byId.TryGetValue(catalogId, out prefab) && prefab != null;
        }

        void OnValidate() => _byId = null;

        void Rebuild()
        {
            _byId = new Dictionary<string, GameObject>(_entries.Length);
            foreach (var e in _entries)
                if (!string.IsNullOrEmpty(e.id)) _byId[e.id] = e.prefab;
        }
    }
}
